1  import type {StackScreenProps} from '@react-navigation/stack';
     2  import React from 'react';
     3  import {View} from 'react-native';
     4  import {withOnyx} from 'react-native-onyx';
     5  import type {OnyxEntry} from 'react-native-onyx';
     6  import HeaderWithBackButton from '@components/HeaderWithBackButton';
     7  import * as Expensicons from '@components/Icon/Expensicons';
     8  import * as Illustrations from '@components/Icon/Illustrations';
     9  import type {MenuItemWithLink} from '@components/MenuItemList';
    10  import ScreenWrapper from '@components/ScreenWrapper';
    11  import ScrollView from '@components/ScrollView';
    12  import Section from '@components/Section';
    13  import Text from '@components/Text';
    14  import useLocalize from '@hooks/useLocalize';
    15  import useThemeStyles from '@hooks/useThemeStyles';
    16  import Navigation from '@libs/Navigation/Navigation';
    17  import type {SettingsNavigatorParamList} from '@libs/Navigation/types';
    18  import * as Link from '@userActions/Link';
    19  import * as Report from '@userActions/Report';
    20  import CONST from '@src/CONST';
    21  import ONYXKEYS from '@src/ONYXKEYS';
    22  import ROUTES from '@src/ROUTES';
    23  import type SCREENS from '@src/SCREENS';
    24  import type {Account} from '@src/types/onyx';
    25
    26  type GetAssistanceOnyxProps = {
    27      /** The details about the account that the user is signing in with */
    28      account: OnyxEntry<Account>;
    29  };
    30
    31  type GetAssistancePageProps = GetAssistanceOnyxProps & StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.GET_ASSISTANCE>;
    32
    33  function GetAssistancePage({route, account}: GetAssistancePageProps) {
    34      const styles = useThemeStyles();
    35      const {translate} = useLocalize();
    36      const navigateBackTo = route?.params.backTo || ROUTES.SETTINGS_CONTACT_METHODS.getRoute();
    37      const menuItems: MenuItemWithLink[] = [
    38          {
    39              title: translate('getAssistancePage.chatWithConcierge'),
    40              onPress: () => Report.navigateToConciergeChat(true),
    41              icon: Expensicons.ChatBubble,
    42              shouldShowRightIcon: true,
    43              wrapperStyle: [styles.cardMenuItem],
    44          },
    45          {
    46              title: translate('getAssistancePage.exploreHelpDocs'),
    47              onPress: () => Link.openExternalLink(CONST.NEWHELP_URL),
    48              icon: Expensicons.QuestionMark,
    49              shouldShowRightIcon: true,
    50              iconRight: Expensicons.NewWindow,
    51              wrapperStyle: [styles.cardMenuItem],
    52              link: CONST.NEWHELP_URL,
    53          },
    54      ];
    55
    56      // If the user is eligible for calls with their Guide, add the 'Schedule a setup call' item at the second position in the list
    57      const guideCalendarLink = account?.guideCalendarLink;
    58      if (guideCalendarLink) {
    59          menuItems.splice(1, 0, {
    60              title: translate('getAssistancePage.scheduleSetupCall'),
    61              onPress: () => Link.openExternalLink(guideCalendarLink),
    62              icon: Expensicons.Phone,
    63              shouldShowRightIcon: true,
    64              iconRight: Expensicons.NewWindow,
    65              wrapperStyle: [styles.cardMenuItem],
    66              link: guideCalendarLink,
    67          });
    68      }
    69
    70      return (
    71          <ScreenWrapper testID={GetAssistancePage.displayName}>
    72              <HeaderWithBackButton
    73                  title={translate('getAssistancePage.title')}
    74                  onBackButtonPress={() => Navigation.goBack(navigateBackTo)}
    75              />
    76              <ScrollView>
    77                  <Section
    78                      title={translate('getAssistancePage.subtitle')}
    79                      icon={Illustrations.ConciergeNew}
    80                      menuItems={menuItems}
    81                  >
    82                      <View style={styles.mv3}>
    83                          <Text>{translate('getAssistancePage.description')}</Text>
    84                      </View>
    85                  </Section>
    86              </ScrollView>
    87          </ScreenWrapper>
    88      );
    89  }
    90
    91  GetAssistancePage.displayName = 'GetAssistancePage';
    92
    93  export default withOnyx<GetAssistancePageProps, GetAssistanceOnyxProps>({
    94      account: {
    95          key: ONYXKEYS.ACCOUNT,
    96          selector: (account) => account && {guideCalendarLink: account.guideCalendarLink},
    97      },
    98  })(GetAssistancePage);
